'use strict';

const fs = require('fs');
const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

if (data.length === 0 || !data[0]) process.exit(0);

let idx = 0;
const budget = data[idx++];
const n = data[idx++];
const m = data[idx++];

const graph = Array.from({ length: n }, () => []);

for (let i = 0; i < m; i++) {
  const a = data[idx++] - 1;
  const b = data[idx++] - 1;
  const time = data[idx++];
  const cost = data[idx++];

  graph[a].push([b, time, cost]);
  graph[b].push([a, time, cost]);
}

const start = data[idx++] - 1;
const target = data[idx++] - 1;
const width = budget + 1;
const dist = new Float64Array(n * width);
dist.fill(Infinity);

const startState = start * width;
dist[startState] = 0;

const heapState = [];
const heapTime = [];

function push(state, time) {
  let i = heapState.length;
  while (i > 0) {
    const parent = (i - 1) >> 1;
    if (heapTime[parent] <= time) break;
    heapState[i] = heapState[parent];
    heapTime[i] = heapTime[parent];
    i = parent;
  }
  heapState[i] = state;
  heapTime[i] = time;
}

let poppedTime = 0;

function pop() {
  const state = heapState[0];
  poppedTime = heapTime[0];

  const last = heapState.length - 1;
  const lastState = heapState[last];
  const lastTime = heapTime[last];
  heapState.length = last;
  heapTime.length = last;

  if (last > 0) {
    let i = 0;
    while (true) {
      const left = i * 2 + 1;
      if (left >= last) break;
      const right = left + 1;
      let child = left;
      if (right < last && heapTime[right] < heapTime[left]) child = right;
      if (heapTime[child] >= lastTime) break;
      heapState[i] = heapState[child];
      heapTime[i] = heapTime[child];
      i = child;
    }
    heapState[i] = lastState;
    heapTime[i] = lastTime;
  }

  return state;
}

push(startState, 0);

while (heapState.length > 0) {
  const state = pop();
  const time = poppedTime;

  if (time !== dist[state]) continue;

  const node = Math.floor(state / width);
  const costSoFar = state % width;

  if (node === target) {
    console.log(time);
    process.exit(0);
  }

  for (const [next, travelTime, price] of graph[node]) {
    const newCost = costSoFar + price;
    if (newCost > budget) continue;

    const nextState = next * width + newCost;
    const newTime = time + travelTime;

    if (newTime < dist[nextState]) {
      dist[nextState] = newTime;
      push(nextState, newTime);
    }
  }
}

console.log(-1);
